mapper.select:
SELECT ei.elderly_id AS elderlyId, ei.name AS name, ei.check_in_time AS checkInTime, ei.bed_id AS bedId, ei.check_out_time AS checkOutTime, ci.check_in_date AS checkInDate, ci.check_out_date As checkOutDate, ci.checkout_type AS checkoutType, ci.approval_status AS approvalStatus, ci.approval_person AS approvalPerson, ci.approval_time AS approvalTime FROM elderly_info ei,check_out_requests ci WHERE ei.elderly_id = ci.elderly_id
AND ei.name LIKE CONCAT('%', #{name}, '%')
AND ei.bed_id = #{bedId}
AND ci.check_in_date = #{checkInDate}

SELECT COUNT(*)
FROM check_out_requests
WHERE elderly_id = #{elderlyId}
